"use strict";

var _utilities = require("../../../utilities");
var _FieldOfficesFilter = require("../FieldOfficesFilter.utils");
describe('FieldOfficesFilter.utils', function () {
  describe('convertBrandLocationGroupsToFilterOptions', function () {
    it('return empty', function () {
      expect((0, _FieldOfficesFilter.convertBrandLocationGroupsToFilterOptions)(null)).toEqual([]);
    });
    it('should convert Brand Location Groups To Filter Options ', function () {
      var brandLocationGroups = [{
        name: 'name123'
      }];
      var options = [{
        id: 'name123',
        label: 'name123'
      }];
      expect((0, _FieldOfficesFilter.convertBrandLocationGroupsToFilterOptions)(brandLocationGroups)).toEqual(options);
    });
  });
  describe('prependFilterName', function () {
    it('should prepend', function () {
      var callback = jest.fn();
      (0, _FieldOfficesFilter.prependFilterName)(callback)('test');
      expect(callback.mock.calls[0][0]).toEqual(_utilities.FILTER_NAMES.brandLocationGroups);
      expect(callback.mock.calls[0][1]).toEqual('test');
    });
  });
});